<template>
 <main class="workbench"><header class="wb-head"><div><span class="wb-kicker">SUPERVISED DATASETS</span><h1>SFT 数据集</h1><p>从已有准备数据构建 messages，整批人工审核后发布固定版本并导出。此页面不执行训练。</p></div><button :disabled="busy" @click="newDraft">新建数据集</button></header><ScenarioPath current="/sft-datasets" />
 <p v-if="error" class="wb-error" role="alert">{{ error }}</p><p v-if="notice" class="wb-success" role="status">{{ notice }}</p>
 <div class="wb-grid"><aside class="wb-panel"><h2>数据集</h2><div class="wb-list"><button v-for="item in items" :key="item.id" :disabled="busy" :class="{selected:current?.id===item.id}" @click="open(item.id)"><strong>{{ item.name }}</strong><small>{{ state(item.status) }} · {{ item.row_count }} 行</small></button></div><p v-if="!items.length" class="wb-empty">暂无 SFT 数据集。</p><button v-if="next" :disabled="busy" @click="load(true)">更多数据集</button></aside>
 <div class="wb-stack sft-detail">
 <section v-if="executionMode" class="wb-panel wb-stack" aria-label="SFT 任务回执"><div class="wb-section-head"><h2>任务构建回执</h2><span v-if="execution" class="wb-badge">{{ state(execution.status) }}</span><button :disabled="busy" @click="openExecution(String(route.query.execution_id))">刷新任务回执</button></div><p>任务只构建待审核候选，完成不代表已审核或发布。</p><p v-if="execution?.error" class="wb-error">{{ execution.error }}</p><p v-if="!current" class="wb-muted">当前尚无可打开的数据集候选，请以真实任务状态为准。</p><RouterLink to="/tasks">返回任务中心</RouterLink></section>
 <form v-if="!current && !executionMode" class="wb-panel wb-stack" @submit.prevent="create"><h2>构建设置</h2><label class="wb-label">数据集名称<input v-model="name" :disabled="busy" required /></label><ScenarioAssetSelect v-model="source" prepared-only :disabled="busy" @selected="asset=$event" /><StandardVersionSelect v-model="standardID" :task-types="['qa']" :disabled="busy" @selected="standard=$event" /><fieldset class="scenario-fieldset" :disabled="busy"><div class="wb-form"><label>数据格式<select aria-label="数据格式" v-model="format"><option value="qa">问答列 → user / assistant</option><option value="messages">messages / tools JSON 列</option></select></label><template v-if="format==='qa'"><label>问题列<input v-model="columns.question" required /></label><label>参考答案列<input v-model="columns.reference_answer" required /></label></template><template v-else><label>messages 列<input v-model="columns.messages" required /></label><label>tools 列（可选）<input v-model="columns.tools" /></label></template><label>split 列（可选）<input v-model="columns.split" placeholder="train / validation / test；不选则 train" /></label><label>分组列（可选）<input v-model="columns.group" /></label></div><p class="wb-footnote">最多 1,000 行。messages 和 tools 单元格必须是原始 JSON 字符串，服务端校验整批数据；不补造回答或工具调用。</p><button class="primary" :disabled="!asset || !standard" type="submit">构建待审核数据集</button></fieldset></form>
 <div v-else-if="current" class="wb-stack"><section class="wb-panel wb-stack"><div class="wb-section-head"><h2>{{ current.name }}</h2><span class="wb-badge">{{ state(current.status) }}</span><button :disabled="busy" @click="open(current.id)">刷新</button></div><RouterLink :to="{path:'/sft-datasets',query:{dataset_id:current.id}}">打开此数据集记录链接</RouterLink><p class="wb-footnote">版本 {{ current.version }} · {{ current.id }} · 来源 {{ current.source_ref_id }}</p><div class="wb-metrics"><span><strong>{{ current.row_count }}</strong><small>总行数</small></span><span v-for="(count,split) in current.split_counts" :key="split"><strong>{{ count }}</strong><small>{{ split }}</small></span></div><p class="wb-footnote">内容摘要 {{ current.content_digest }}</p><label class="wb-label">整批审核说明<textarea v-model="comment" :disabled="busy" /></label><label class="wb-checkbox"><input v-model="reviewConfirmed" type="checkbox" :disabled="busy" />我已检查数据内容、分组与切分，确认整批审核结论</label><div class="wb-actions"><button :disabled="busy || !reviewConfirmed" @click="review('approved')">审核通过</button><button :disabled="busy || !reviewConfirmed" @click="review('rejected')">驳回数据集</button><button class="primary" :disabled="busy || current.status!=='approved'" @click="publish">发布固定版本</button></div><p class="wb-footnote">错误数据请在来源修正后重新准备、重新构建；这里不会逐行改写回答。发布与审核为两个独立操作。</p></section>
 <section class="wb-panel"><h2>数据集样本</h2><article v-for="row in rows" :key="row.row_id" class="standard-version"><h3>源记录 {{ row.source_row_index+1 }} · {{ row.split }}<span v-if="row.group"> · {{ row.group }}</span></h3><pre class="wb-code">{{ JSON.stringify({messages:row.messages,...(row.tools?{tools:row.tools}:{})},null,2) }}</pre></article><button v-if="rowNext" :disabled="busy" @click="moreRows">更多数据行</button></section>
 <section class="wb-panel"><h2>已发布版本</h2><div v-for="v in versions" :key="v.id" class="standard-version"><strong>{{ v.id }} · {{ v.row_count }} 行</strong><p class="wb-footnote">{{ v.content_digest }}</p><button :disabled="busy" @click="download(v.id)">导出此版本 JSONL</button></div><p v-if="!versions.length" class="wb-empty">尚未发布。</p><button v-if="versionNext" :disabled="busy" @click="moreVersions">更多已发布版本</button></section></div></div></div></main>
</template>
<script setup lang="ts">
import {onMounted,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuthStore} from '@/stores/auth'
import {sftApi,type SFTDataset,type SFTVersion,type SFTRow,type SFTInput,type SFTExecution} from '@/api/scenario/sft'
import type {AssetRef} from '@/api/lifecycle'
import type {StandardVersion} from '@/api/governance/standards'
import ScenarioAssetSelect from './ScenarioAssetSelect.vue'
import StandardVersionSelect from './StandardVersionSelect.vue'
import ScenarioPath from './ScenarioPath.vue'
import {useScenarioSession} from './useScenarioSession'
import '@/components/workbench/workbench.css'
import './scenario.css'
const route=useRoute(),auth=useAuthStore(),items=ref<SFTDataset[]>([]),next=ref(''),current=ref<SFTDataset>(),rows=ref<SFTRow[]>([]),rowNext=ref(''),versions=ref<SFTVersion[]>([]),versionNext=ref(''),source=ref(''),asset=ref<AssetRef>(),standardID=ref(''),standard=ref<StandardVersion>(),name=ref(''),format=ref<'qa'|'messages'>('qa'),columns=reactive({question:'',reference_answer:'',messages:'',tools:'',split:'',group:''}),comment=ref(''),reviewConfirmed=ref(false)
const execution=ref<SFTExecution>(),executionMode=ref(false)
const session=useScenarioSession(()=>{items.value=[];next.value='';newDraft();void initialize()}),{busy,error,notice}=session
const state=(s:string)=>({draft:'待人工审核',approved:'审核通过',rejected:'已驳回',published:'已发布',queued:'已排队',running:'构建中',succeeded:'构建成功',completed:'构建成功',failed:'构建失败',cancel_requested:'已申请取消',cancelled:'已取消',timed_out:'已超时'}[s]||s)
function clearDetail(){current.value=undefined;rows.value=[];rowNext.value='';versions.value=[];versionNext.value='';comment.value='';reviewConfirmed.value=false}
function newDraft(){session.invalidate();clearDetail();execution.value=undefined;executionMode.value=false;name.value='';source.value='';asset.value=undefined;standardID.value='';standard.value=undefined;Object.keys(columns).forEach(k=>columns[k as keyof typeof columns]='')}
async function load(append=false){await session.run(async valid=>{const r=await sftApi.list(append?next.value:'');if(!valid())return;items.value=Array.from(new Map([...(append?items.value:[]),...(r.data?.items||[])].map(v=>[v.id,v])).values());next.value=r.data?.next_cursor||''})}
async function loadDetail(id:string,valid:()=>boolean){const r=await sftApi.get(id);if(!valid())return;if(!r.data)throw new Error('数据集不存在或无权读取');const [a,b]=await Promise.all([sftApi.rows(id),sftApi.versions(id)]);if(!valid())return;current.value=r.data;rows.value=a.data?.items||[];rowNext.value=a.data?.next_cursor||'';versions.value=b.data?.items||[];versionNext.value=b.data?.next_cursor||'';comment.value='';reviewConfirmed.value=false}
async function open(id:string){session.invalidate();clearDetail();if(execution.value?.domain_id!==id){execution.value=undefined;executionMode.value=false}await session.run(valid=>loadDetail(id,valid))}
async function openExecution(id:string){session.invalidate();clearDetail();execution.value=undefined;executionMode.value=true;await session.run(async valid=>{const result=(await sftApi.execution(id)).data;if(!valid())return;if(!result||result.id!==id||result.domain_kind!=='sft_dataset')throw new Error('该任务不是可读取的 SFT 构建回执');execution.value=result;if(result.status==='completed'&&result.domain_id)await loadDetail(result.domain_id,valid)})}
async function create(){if(!asset.value||!standard.value)return;await session.run(async valid=>{const mapped:SFTInput['columns']=format.value==='qa'?{question:columns.question.trim(),reference_answer:columns.reference_answer.trim()}:{messages:columns.messages.trim(),...(columns.tools.trim()?{tools:columns.tools.trim()}:{})};if(columns.split.trim())mapped.split=columns.split.trim();if(columns.group.trim())mapped.group=columns.group.trim();const r=await sftApi.create({name:name.value.trim(),source_ref_id:source.value,standard_version_id:standardID.value,format:format.value,columns:mapped});if(!valid())return;if(!r.data)throw new Error('未收到创建回执');await loadDetail(r.data.id,valid);if(valid()){items.value=[r.data,...items.value.filter(v=>v.id!==r.data!.id)];notice.value='已构建待审核数据集，尚未发布。'}})}
async function review(decision:'approved'|'rejected'){if(!current.value||!reviewConfirmed.value)return;const id=current.value.id,version=current.value.version;await session.run(async valid=>{await sftApi.review(id,version,decision,comment.value);if(!valid())return;await loadDetail(id,valid);if(valid())notice.value='已保存整批审核结论。'})}
async function publish(){if(!current.value||current.value.status!=='approved')return;const id=current.value.id,version=current.value.version;await session.run(async valid=>{await sftApi.publish(id,version);if(!valid())return;await loadDetail(id,valid);if(valid())notice.value='固定版本已发布，可导出 JSONL。'})}
async function moreRows(){if(current.value)await session.run(async valid=>{const r=await sftApi.rows(current.value!.id,rowNext.value);if(!valid())return;rows.value=[...rows.value,...(r.data?.items||[])];rowNext.value=r.data?.next_cursor||''})}
async function moreVersions(){if(current.value)await session.run(async valid=>{const r=await sftApi.versions(current.value!.id,versionNext.value);if(!valid())return;versions.value=[...versions.value,...(r.data?.items||[])];versionNext.value=r.data?.next_cursor||''})}
async function download(id:string){await session.run(async valid=>{const response=await fetch(`/api/v1/sft-dataset-versions/${encodeURIComponent(id)}/export`,{headers:{Authorization:`Bearer ${auth.token}`,...(auth.currentTenant?{'X-Tenant-ID':String(auth.currentTenant.id)}:{})}});if(!valid())return;if(!response.ok)throw new Error(`导出失败 (${response.status})`);const blob=await response.blob();if(!valid())return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sft-${id}.jsonl`;a.click();URL.revokeObjectURL(url);notice.value='已导出固定版本；未启动训练。'})}
async function initialize(){const valid=session.capture();await load();if(!valid())return;if(typeof route.query.execution_id==='string')await openExecution(route.query.execution_id);else if(typeof route.query.dataset_id==='string')await open(route.query.dataset_id);else{source.value=typeof route.query.source_ref==='string'?route.query.source_ref:'';standardID.value=typeof route.query.standard_version_id==='string'?route.query.standard_version_id:''}}
watch(()=>[route.query.execution_id,route.query.dataset_id,route.query.source_ref,route.query.standard_version_id],()=>{newDraft();void initialize()})
onMounted(initialize)
</script>

<style scoped>
.sft-detail { min-width: 0; }
.sft-detail .wb-footnote { overflow-wrap: anywhere; }
</style>
